  return (
    <div className="w-full min-w-0">
      <ScrollArea className="w-full">
        <div className="flex w-max min-w-full gap-2 px-1 pt-1 pb-4">
          {movies.map((movie, index) => (
            <MovieCard
              key={movie.id ?? `${movie.title}-${index}`}
              movie={movie}
            />
          ))}
